from __future__ import annotations
from dataclasses import dataclass
from typing import Callable, Hashable, TypeVar
S = TypeVar("S", bound=Hashable)
@dataclass(frozen=True)
class Audit:
    visited: tuple[S, ...]
    closed: bool
    fixed_indices: tuple[int, ...]
    consistent: bool
def audit(step: Callable[[S], S], start: S, period: int) -> Audit:
    if period <= 0: raise ValueError("period must be positive")
    visited: list[S] = []; fixed: list[int] = []; state = start
    for k in range(period):
        visited.append(state); nxt = step(state)
        if nxt == state: fixed.append(k)
        state = nxt
    return Audit(tuple(visited), state == start, tuple(fixed), len(fixed) == period)
def flip(x: bool) -> bool: return not x
for p in range(1, 9): print(p, audit(flip, True, p))

