from __future__ import annotations
from dataclasses import dataclass
from typing import Callable, Generic, Hashable, TypeVar
S = TypeVar("S", bound=Hashable)
@dataclass(frozen=True)
class OrbitResult(Generic[S]):
    endpoint: S
    closed: bool
    fixed_indices: tuple[int, ...]
    consistent: bool
def classify_orbit(step: Callable[[S], S], start: S, period: int) -> OrbitResult[S]:
    if period <= 0: raise ValueError("period must be positive")
    fixed: list[int] = []; state = start
    for index in range(period):
        nxt = step(state)
        if nxt == state: fixed.append(index)
        state = nxt
    return OrbitResult(state, state == start, tuple(fixed), len(fixed) == period)

from __future__ import annotations
from typing import Callable, Iterable, TypeVar
S = TypeVar("S")
def audit_idempotence(step: Callable[[S], S], states: Iterable[S]) -> tuple[bool, list[S]]:
    failures: list[S] = []
    for state in states:
        if step(step(state)) != step(state): failures.append(state)
    return not failures, failures

